def criticalConnections(V, adj):
    def dfs(node, parent, low, disc, time, visited, bridges):
        visited[node] = True
        disc[node] = time
        low[node] = time
        time += 1
        for neighbor in adj[node]:
            if not visited[neighbor]:
                dfs(neighbor, node, low, disc, time, visited, bridges)
                low[node] = min(low[node], low[neighbor])
                if low[neighbor] > disc[node]:
                    bridges.append(sorted((node, neighbor)))
            elif neighbor != parent:
                low[node] = min(low[node], disc[neighbor])

    visited = [False] * V
    disc = [float('inf')] * V
    low = [float('inf')] * V
    bridges = []
    time = 0

    for i in range(V):
        if not visited[i]:
            dfs(i, -1, low, disc, time, visited, bridges)

    return sorted(bridges)
